import React, { useState, useEffect, useRef } from 'react';

interface LandingPageProps {
  onSelectView: (view: 'cli' | 'gui') => void;
}

const LandingPage: React.FC<LandingPageProps> = ({ onSelectView }) => {
  const [photoUrl, setPhotoUrl] = useState<string | null>(null);
  const [bio, setBio] = useState<string>(
    "I am a Computer Science major at Strathmore University, deeply passionate about cybersecurity, distributed systems, software development, and AI/ML. Outside of academics, I'm an avid sportsman, actively involved in rugby and hitting the gym. My defining characteristic is grit; you could say it's my middle name."
  );

  const handlePhotoUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setPhotoUrl(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="landing-container" style={{ backgroundColor: '#1a1a1a', color: '#d9d9d9', fontFamily: "'Noto Sans', sans-serif" }}>
      <div className="boot-screen" style={{ width: '80%', maxWidth: '900px', margin: 'auto', padding: '20px', boxSizing: 'border-box' }}>
        <p>BIOS Version: 2.1.0</p>
        <p>Copyright (C) 2025 Daryn Ongera. All Rights Reserved.</p>
        <p>CPU: Intel(R) Core(TM) i9-10900K CPU @ 3.70GHz</p>
        <p>Memory Test: 65536MB OK</p>
        <p>Initializing USB Controllers... Done.</p>
        <p>Detecting Hard Drives... Done.</p>
        <p>Loading Operating System...</p>
        <p>Welcome to Daryn Ongera's Portfolio</p>
        <p></p>

        <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', margin: '40px 0' }}>
          <div style={{ marginBottom: '20px', border: '2px solid #007ACC', borderRadius: '50%', width: '180px', height: '180px', display: 'flex', justifyContent: 'center', alignItems: 'center', overflow: 'hidden', position: 'relative' }}>
            {photoUrl ? (
              <img src={photoUrl} alt="Profile" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
            ) : (
              <span style={{ color: '#d9d9d9', fontSize: '0.9em' }}>Upload Photo</span>
            )}
            <input
              type="file"
              accept="image/*"
              onChange={handlePhotoUpload}
              style={{ position: 'absolute', top: 0, left: 0, width: '100%', height: '100%', opacity: 0, cursor: 'pointer' }}
            />
          </div>
          <div style={{ textAlign: 'center', maxWidth: '600px' }}>
            <h2 style={{ color: '#007ACC', marginBottom: '10px', fontSize: '1.8em' }}>About Me</h2>
            <p style={{ lineHeight: '1.6', fontSize: '1em' }}>{bio}</p>
          </div>
        </div>

        <p>Please select an interface:</p>
        <div className="choice-container" style={{ display: 'flex', justifyContent: 'center', marginTop: '20px' }}>
          <div className="landing-box" onClick={() => onSelectView('cli')} style={{ width: '200px', height: '200px', border: '2px solid #007ACC', margin: '20px', display: 'flex', flexDirection: 'column', justifyContent: 'center', alignItems: 'center', cursor: 'pointer', transition: 'all 0.3s ease', color: '#d9d9d9' }}>
            <h1 style={{ fontSize: '2em', margin: '0' }}>CLI</h1>
            <p style={{ fontSize: '1em', margin: '5px 0 0 0' }}>Launch Command Line Interface</p>
          </div>
          <div className="landing-box" onClick={() => onSelectView('gui')} style={{ width: '200px', height: '200px', border: '2px solid #007ACC', margin: '20px', display: 'flex', flexDirection: 'column', justifyContent: 'center', alignItems: 'center', cursor: 'pointer', transition: 'all 0.3s ease', color: '#d9d9d9' }}>
            <h1 style={{ fontSize: '2em', margin: '0' }}>GUI</h1>
            <p style={{ fontSize: '1em', margin: '5px 0 0 0' }}>Explore Graphical User Interface</p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default LandingPage;
